const agentCoreRecipeVersion = "1"

// Generated by aws-connector-artifacts/scripts/sync-connector-distros.py.
//
//go:embed data/agentcore_distros.json
var agentCoreDistroJSON []byte

// AgentCoreDistros returns concrete activation profiles, not language-agnostic plugin names.
func AgentCoreDistros(language string) []baseapi.InstrumentationDistro {
	var out []baseapi.InstrumentationDistro
	var catalog []baseapi.InstrumentationDistro
	if err := json.Unmarshal(agentCoreDistroJSON, &catalog); err != nil {
		panic(err)
	}
	for _, d := range catalog {
		if d.Language == language {
			out = append(out, d)
		}
	}
	return out
}
func ResolveAgentCoreDistro(language, name string) (baseapi.InstrumentationDistro, error) {
	for _, d := range AgentCoreDistros(language) {
		if d.Name == name || (name == "" && d.IsDefault) {
			return d, nil
		}
	}
	return baseapi.InstrumentationDistro{}, fmt.Errorf("%w: AgentCore distro %q for language %q", ErrUnsupportedRuntime, name, language)
}

func agentCoreEligible(r agentcore.Runtime, d baseapi.InstrumentationDistro) error {
	if r.Instances {
		return fmt.Errorf("%w: AgentCore Instances are not qualified; use manual OTel deployment", ErrUnsupportedInstrumentation)
	}
	if r.Protocol != "" && r.Protocol != "HTTP" {
		return fmt.Errorf("%w: AgentCore protocol %s is not qualified", ErrUnsupportedInstrumentation, r.Protocol)
	}
	if r.Package.Version != 1 || r.Package.Language != d.Language || !slices.Contains(r.Package.Distros, d.Name) {
		return fmt.Errorf("%w: the AgentCore artifact does not carry the %s SDK; add %s to the agent's dependencies (or the carrier bundle) and redeploy before enabling instrumentation", ErrUnsupportedInstrumentation, d.Name, agentCoreDistroDependency(d.Name))
	}
	// ADOT starts through the customer's own startup, so only the Odigos package depends on the module format.
	if d.Language == "nodejs" && agentCorePackageSDK(r.Package) == agentCoreSDKOdigos && r.Package.ModuleFormat != "commonjs" {
		return fmt.Errorf("%w: native ESM needs explicit SDK initialization; the automatic AgentCore recipe requires CommonJS", ErrUnsupportedInstrumentation)
	}
	return nil
}

func agentCoreTarget(t dest.OTLPTarget) error {
	if t.HTTPEndpoint == "" || t.Endpoint != "" {
		return fmt.Errorf("AgentCore requires a global otlphttp destination in this phase; managed collectors and direct gRPC routing are not enabled")
	}
	u, err := url.Parse(t.HTTPEndpoint)
	if err != nil || u.Host == "" || (u.Scheme != "http" && u.Scheme != "https") || u.User != nil || u.RawQuery != "" || u.Fragment != "" {
		return fmt.Errorf("AgentCore requires an HTTP(S) OTLP base URL without credentials, query or fragment")
	}
	if strings.HasSuffix(strings.TrimRight(u.Path, "/"), "/v1/traces") || strings.HasSuffix(strings.TrimRight(u.Path, "/"), "/v1/logs") || strings.HasSuffix(strings.TrimRight(u.Path, "/"), "/v1/metrics") {
		return fmt.Errorf("AgentCore OTLP endpoint must be a base URL, without a per-signal /v1 path")
	}
	if !t.Traces && !t.Metrics && !t.Logs {
		return fmt.Errorf("AgentCore cannot export the selected signals (profiles are not supported)")
	}
	return nil
}

// agentCoreOdigosEnv configures the Odigos package. It owns every per-signal endpoint/header so stale ADOT
// defaults cannot override the connector-wide destination. No collector health or regional route is an input.
func agentCoreOdigosEnv(d baseapi.InstrumentationDistro, service string, t dest.OTLPTarget, headers map[string]string) map[string]string {
	ep := strings.TrimRight(t.HTTPEndpoint, "/")
	env := map[string]string{
		agentcore.EnabledEnv: "true", agentcore.DistroEnv: d.Name,
		"DISABLE_ADOT_OBSERVABILITY": "true", "AGENT_OBSERVABILITY_ENABLED": "false",
		"OTEL_SERVICE_NAME": service, "OTEL_EXPORTER_OTLP_ENDPOINT": ep, "OTEL_EXPORTER_OTLP_PROTOCOL": "http/protobuf",
		"OTEL_SDK_DISABLED": "false",
		"OTEL_PROPAGATORS":  "tracecontext,baggage,xray", "OTEL_TRACES_SAMPLER": "parentbased_always_on",
		"OTEL_AWS_APPLICATION_SIGNALS_ENABLED": "false", "OTEL_AWS_DYNAMIC_INSTRUMENTATION_ENABLED": "false",
		"OTEL_INSTRUMENTATION_GENAI_CAPTURE_MESSAGE_CONTENT": "false", "TRACELOOP_TRACE_CONTENT": "false",
		"OTEL_PYTHON_LOGGING_AUTO_INSTRUMENTATION_ENABLED": "true",
	}
	for signal, enabled := range map[string]bool{"TRACES": t.Traces, "METRICS": t.Metrics, "LOGS": t.Logs} {
		exporter := "none"
		if enabled {
			exporter = "otlp"
		}
		env["OTEL_"+signal+"_EXPORTER"] = exporter
		env["OTEL_EXPORTER_OTLP_"+signal+"_ENDPOINT"] = ep + "/v1/" + strings.ToLower(signal)
		env["OTEL_EXPORTER_OTLP_"+signal+"_PROTOCOL"] = "http/protobuf"
		// Removal is important: signal-specific auth otherwise overrides the shared header.
		env["OTEL_EXPORTER_OTLP_"+signal+"_HEADERS"] = ""
	}
	var headerParts []string
	for key, value := range headers {
		encode := func(s string) string { return strings.ReplaceAll(url.QueryEscape(s), "+", "%20") }
		headerParts = append(headerParts, encode(key)+"="+encode(value))
	}
	sort.Strings(headerParts)
	env["OTEL_EXPORTER_OTLP_HEADERS"] = strings.Join(headerParts, ",")
	if d.Language == "python" {
		if strings.HasSuffix(d.Name, "-adot") {
			env["OTEL_PYTHON_DISTRO"] = "aws_distro"
			env["OTEL_PYTHON_CONFIGURATOR"] = "aws_configurator"
			env["OTEL_PYTHON_DISABLED_INSTRUMENTATIONS"] = "boto3"
		} else {
			env["OTEL_PYTHON_DISTRO"] = "distro"
			env["OTEL_PYTHON_CONFIGURATOR"] = "configurator"
			env["OTEL_PYTHON_DISABLED_INSTRUMENTATIONS"] = "botocore,aws_langchain,aws_openai_agents,aws_llama-index,aws_crewai,aws_mcp"
		}
	}
	return env
}

// agentCoreADOTEnv configures an ADOT distribution the artifact already runs. No Odigos code runs with it, so
// the bootstrap's switches are removed. Dropping the X-Ray propagator is what environment can do in place of
// the bootstrap's invocation rooting: with an uninstrumented caller AgentCore sends only X-Amzn-Trace-Id, so the
// agent's server span becomes a root instead of a child of AgentCore's span.
func agentCoreADOTEnv(d baseapi.InstrumentationDistro, service string, t dest.OTLPTarget, headers map[string]string) map[string]string {
	env := agentCoreOdigosEnv(d, service, t, headers)
	env[agentcore.EnabledEnv] = ""
	env[agentcore.DistroEnv] = ""
	env["OTEL_PROPAGATORS"] = "tracecontext,baggage"
	return env
}

// agentCoreRecipe is the environment adoption applies for the SDK it starts.
func agentCoreRecipe(sdk agentCoreSDKKind, d baseapi.InstrumentationDistro, service string, t dest.OTLPTarget, headers map[string]string) map[string]string {
	if sdk == agentCoreSDKADOT {
		return agentCoreADOTEnv(d, service, t, headers)
	}
	return agentCoreOdigosEnv(d, service, t, headers)
}

type agentCoreMarker struct {
	Version  int    `json:"v"`
	Snapshot string `json:"snapshot"`
	Distro   string `json:"distro"`
}
type agentCoreSnapshot struct {
	Previous          map[string]*string    `json:"previous"`
	Applied           map[string]string     `json:"applied"`
	OriginalArtifact  *agentCoreArtifactRef `json:"originalArtifact,omitempty"`
	InstalledArtifact *agentCoreArtifactRef `json:"installedArtifact,omitempty"`
	// SDK is which carried SDK the installation started. Snapshots written before it was recorded hold the
	// earlier delivery name in Mode instead ("adopt" for ADOT, "package" or nothing for the Odigos package); both
	// stay omitempty so those snapshots keep their digest when re-marshalled. Read through agentCoreSnapshotSDK.
	Mode string           `json:"mode,omitempty"`
	SDK  agentCoreSDKKind `json:"sdk,omitempty"`
}

// customerEntryPoint is the live artifact with the customer's entry point back, when a redeploy replaced the code but
// kept the entry point Odigos set (the Odigos package's start wrapper alone, whose script is in the managed environment).
// nil when the live entry point is not Odigos's.
func (s agentCoreSnapshot) customerEntryPoint(actual agentCoreArtifactRef) *agentCoreArtifactRef {
	if s.InstalledArtifact == nil || s.OriginalArtifact == nil || slices.Equal(s.InstalledArtifact.EntryPoint, s.OriginalArtifact.EntryPoint) ||
		!slices.Equal(actual.EntryPoint, s.InstalledArtifact.EntryPoint) {
		return nil
	}
	next := actual
	next.EntryPoint = append([]string(nil), s.OriginalArtifact.EntryPoint...)
	return &next
}

func parseAgentCoreMarker(raw string) (agentCoreMarker, error) {
	var m agentCoreMarker
	if err := json.Unmarshal([]byte(raw), &m); err != nil || m.Version != 1 || len(m.Snapshot) != 64 || m.Distro == "" {
		return m, fmt.Errorf("invalid AgentCore ownership marker; refusing to overwrite or remove instrumentation")
	}
	return m, nil
}

func agentCoreDiff(current, want map[string]string) []string {
	var missing []string
	for key, value := range want {
		if current[key] != value {
			missing = append(missing, key)
		}
	}
	sort.Strings(missing)
	return missing
}
func validateAgentCoreEnv(env map[string]string) error {
	if len(env) > 50 {
		return fmt.Errorf("AgentCore environment would exceed the 50-variable limit")
	}
	for k, v := range env {
		if len(k) > 100 || len(v) > 5000 {
			return fmt.Errorf("AgentCore environment variable %s exceeds the service size limit", k)
		}
	}
	return nil
}

func validateAgentCoreRuntimeEnv(live *ac.GetAgentRuntimeOutput, env map[string]string) error {
	if err := validateAgentCoreEnv(env); err != nil {
		return err
	}
	limit := 4096
	if live.PlatformVersion != nil && *live.PlatformVersion == "V2" {
		limit = 2560
		artifact, err := agentCoreArtifact(live.AgentRuntimeArtifact)
		if err != nil {
			return err
		}
		if artifact.Image == "" {
			limit = 1536
		}
	}
	size := 0
	for k, v := range env {
		size += len(k) + len(v)
	}
	if size > limit {
		return fmt.Errorf("AgentCore environment would use %d bytes, exceeding this platform's %d-byte limit; reduce application/export settings or use manual integration", size, limit)
	}
	return nil
}
func restoreAgentCoreEnv(current map[string]string, snapshot agentCoreSnapshot) (map[string]string, error) {
	next := maps.Clone(current)
	for key, applied := range snapshot.Applied {
		if current[key] != applied {
			return nil, fmt.Errorf("AgentCore managed setting %s changed outside Odigos; refusing rollback until the conflict is resolved", key)
		}
		if old := snapshot.Previous[key]; old != nil {
			next[key] = *old
		} else {
			delete(next, key)
		}
	}
	delete(next, "ODIGOS_MANAGED")
	return next, nil
}
